input.command:
powershell -NoProfile -Command @"
Write-Host '=== ports ==='
foreach (`$p in 8016,5173,8000) {
  `$l = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort `$p -State Listen -ErrorAction SilentlyContinue
  if (`$l) {
    `$owner = (`$l | Select-Object -First 1).OwningProcess
    `$proc = Get-CimInstance Win32_Process -Filter \"ProcessId = `$owner\" -ErrorAction SilentlyContinue
    Write-Host \"port `$p pid=`$owner name=`$(`$proc.Name)\"
    Write-Host (\"  cmd=`\" + (`$proc.CommandLine).Substring(0, [Math]::Min(180, (`$proc.CommandLine).Length)))
  } else { Write-Host \"port `$p LISTEN=none\" }
}
Write-Host '=== health ==='
foreach (`$u in @('http://127.0.0.1:8016/health','http://127.0.0.1:5173/trading')) {
  try {
    `$r = Invoke-WebRequest -Uri `$u -UseBasicParsing -TimeoutSec 5 -Proxy `$null
    Write-Host \"`$u -> `$(`$r.StatusCode)\"
  } catch { Write-Host \"`$u -> FAIL `$(`$_.Exception.Message)\" }
}
Write-Host '=== pid files ==='
Get-Content 'C:\Users\win\Desktop\AI--main\logs\api.pid','C:\Users\win\Desktop\AI--main\logs\frontend.pid','C:\Users\win\Desktop\AI--main\logs\scheduler.pid' -ErrorAction SilentlyContinue
Write-Host '=== recent python ==='
Get-CimInstance Win32_Process -Filter \"Name = 'python.exe'\" | Select-Object ProcessId,@{n='Cmd';e={ if (`$_.CommandLine.Length -gt 160) { `$_.CommandLine.Substring(0,160) } else { `$_.CommandLine } }} | Format-List
"@

input.old_string:
function Test-ProjectListener([int]$Port) {
    $listener = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $Port -State Listen -ErrorAction SilentlyContinue |
        Select-Object -First 1
    if (-not $listener) { return $false }
    $ownerInfo = Get-CimInstance Win32_Process -Filter "ProcessId = $($listener.OwningProcess)" -ErrorAction SilentlyContinue
    $commandLine = [string]$ownerInfo.CommandLine
    if ($commandLine -match "apps\.api\.(main|local_server)") {
        return $commandLine -match "--local-console"
    }
    return $commandLine -match "量化项目.*vite\.js"
}

input.new_string:
function Test-ProjectListener([int]$Port) {
    $listener = Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $Port -State Listen -ErrorAction SilentlyContinue |
        Select-Object -First 1
    if (-not $listener) { return $false }
    $ownerInfo = Get-CimInstance Win32_Process -Filter "ProcessId = $($listener.OwningProcess)" -ErrorAction SilentlyContinue
    $commandLine = [string]$ownerInfo.CommandLine
    if ($commandLine -match "apps\.api\.(main|local_server)") {
        return $commandLine -match "--local-console"
    }
    # Frontend vite: accept this repo path (AI--main). Old hardcode "量化项目" never matched and
    # forced a full DB re-prep (~50s) on every re-launch even when the console was already up.
    $rootEscaped = [regex]::Escape($Root)
    return ($commandLine -match "vite\.js") -and (
        $commandLine -match $rootEscaped -or
        $commandLine -match "frontend[\\/]+admin" -or
        $commandLine -match "量化项目"
    )
}

